#include <stdio.h>

/* 快速幂: 分治计算 a^n mod m
 * 分解: 先求 a^(n/2); 解决: 递归; 合并: 平方后按奇偶补乘
 * T(n) = T(n/2) + O(1) => Θ(log n)(主定理情形2, c*=0, f=Θ(n^0)) */
long long pow_mod(long long a, long long n, long long m) {
    if (n == 0) return 1 % m;              /* 递归基: a^0 = 1 */
    long long half = pow_mod(a, n / 2, m); /* 解决: 子问题 a^(n/2) */
    long long r = half * half % m;         /* 合并: 平方 */
    if (n % 2 == 1) r = r * a % m;         /* n 为奇数再乘一个 a */
    return r;
}

int main(void) {
    long long a, n, m;
    printf("输入 a n m (计算 a^n mod m): ");
    if (scanf("%lld %lld %lld", &a, &n, &m) != 3 || m <= 1) {
        printf("输入无效! 要求 m >= 2\n");
        return 1;
    }
    printf("%lld^%lld mod %lld = %lld\n", a, n, m, pow_mod(a, n, m));
    return 0;
}

#include <stdio.h>

/* 二分查找边界变体: 全部用半开区间 [lo, hi) 模板, 输入需有序 */
int lower_bound(int A[], int n, int x) {   /* 第一个 >= x 的下标 */
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;      /* 防溢出: 不用 (lo+hi)/2 */
        if (A[mid] < x) lo = mid + 1;      /* 排除 [lo, mid] */
        else hi = mid;                     /* 收缩右界, 保持候选 */
    }
    return lo;
}

int upper_bound(int A[], int n, int x) {   /* 第一个 > x 的下标 */
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (A[mid] <= x) lo = mid + 1;     /* 只差这一个比较符 */
        else hi = mid;
    }
    return lo;
}

int main(void) {
    int n, x, A[100];
    printf("输入 n 与待查值 x: ");
    if (scanf("%d %d", &n, &x) != 2 || n < 0 || n > 100) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个有序整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    int lb = lower_bound(A, n, x);
    int ub = upper_bound(A, n, x);
    printf("第一个 >= %d 的下标: %d\n", x, lb);
    printf("第一个 >  %d 的下标: %d\n", x, ub);
    printf("最后一个 <= %d 的下标: %d\n", x, ub - 1);
    printf("%d 的出现次数: %d\n", x, ub - lb);
    return 0;
}

#include <stdio.h>

/* 归并排序 + 逆序对计数: 合并时若左半元素大于右半元素, 累加左半剩余个数 */
long long inv_count = 0;
int tmp[100000];

void merge_sort(int A[], int lo, int hi) {
    if (hi - lo <= 1) return;              /* 递归基: 长度 0/1 已有序 */
    int mid = lo + (hi - lo) / 2;          /* 分解: 均分两半 */
    merge_sort(A, lo, mid);                /* 解决: 左半 */
    merge_sort(A, mid, hi);                /* 解决: 右半 */
    int i = lo, j = mid, k = lo;           /* 合并: 双指针 */
    while (i < mid && j < hi) {
        if (A[i] <= A[j]) tmp[k++] = A[i++];
        else {
            tmp[k++] = A[j++];
            inv_count += mid - i;          /* A[j] 与左半剩余全部构成逆序对 */
        }
    }
    while (i < mid) tmp[k++] = A[i++];
    while (j < hi) tmp[k++] = A[j++];
    for (int t = lo; t < hi; t++) A[t] = tmp[t];
}

int main(void) {
    int n, A[100000];
    printf("输入元素个数 n (<= 100000): ");
    if (scanf("%d", &n) != 1 || n <= 0 || n > 100000) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    merge_sort(A, 0, n);
    printf("排序后: ");
    for (int i = 0; i < n; i++) printf("%d ", A[i]);
    printf("\n逆序对数: %lld\n", inv_count);
    return 0;
}

