#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* 随机化快速排序: Lomuto 划分 + 随机基准, 期望 O(n log n) */
int partition(int A[], int lo, int hi) {
    int r = lo + rand() % (hi - lo + 1);   /* 随机选基准并换到末尾 */
    int t = A[r]; A[r] = A[hi]; A[hi] = t;
    int pivot = A[hi], i = lo - 1;          /* i: < pivot 区末尾 */
    for (int j = lo; j < hi; j++) {
        if (A[j] < pivot) {                 /* 小于基准的放入左区 */
            i++;
            t = A[i]; A[i] = A[j]; A[j] = t;
        }
    }
    t = A[i + 1]; A[i + 1] = A[hi]; A[hi] = t;  /* 基准归位 */
    return i + 1;
}

void quick_sort(int A[], int lo, int hi) {
    if (lo >= hi) return;                    /* 递归基 */
    int p = partition(A, lo, hi);
    quick_sort(A, lo, p - 1);                /* 解决: 左半 */
    quick_sort(A, p + 1, hi);                /* 解决: 右半 */
}

int main(void) {
    int n, A[100000];
    srand((unsigned)time(NULL));
    printf("输入元素个数 n (<= 100000): ");
    if (scanf("%d", &n) != 1 || n <= 0 || n > 100000) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    quick_sort(A, 0, n - 1);
    printf("排序后: ");
    for (int i = 0; i < n; i++) printf("%d ", A[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>

/* 最大子数组: Kadane O(n) 与分治 O(n log n) 对比 */

/* Kadane: 维护以 i 结尾的最大和; 负前缀直接丢弃 */
int kadane(int A[], int n, int *bl, int *br) {
    int best = A[0], cur = A[0], l = 0, r = 0, cur_l = 0;
    *bl = 0; *br = 0;                             /* 全负时区间即 [0, 0] */
    for (int i = 1; i < n; i++) {
        if (cur < 0) { cur = A[i]; cur_l = i; }   /* 负前缀无益, 重开 */
        else cur += A[i];
        if (cur > best) { best = cur; *bl = cur_l; *br = i; }
    }
    return best;
}

/* 跨中点的最大子数组 = 左半最大后缀(含 A[mid-1]) + 右半最大前缀(含 A[mid]) */
int max_cross(int A[], int lo, int mid, int hi, int *bl, int *br) {
    int sum = A[mid - 1], left = A[mid - 1], l = mid - 1;
    for (int i = mid - 2; i >= lo; i--) {   /* 左半最大后缀 */
        sum += A[i];
        if (sum > left) { left = sum; l = i; }
    }
    sum = A[mid]; int right = A[mid], r = mid;
    for (int i = mid + 1; i < hi; i++) {    /* 右半最大前缀 */
        sum += A[i];
        if (sum > right) { right = sum; r = i; }
    }
    *bl = l; *br = r;
    return left + right;
}

/* 分治: [lo, hi) 内最大子数组和, 区间由引用参数带出 */
int dc(int A[], int lo, int hi, int *bl, int *br) {
    if (hi - lo == 1) { *bl = lo; *br = lo; return A[lo]; }
    int mid = lo + (hi - lo) / 2, l1, r1, l2, r2, l3, r3;
    int a = dc(A, lo, mid, &l1, &r1);      /* 解决: 左半 */
    int b = dc(A, mid, hi, &l2, &r2);      /* 解决: 右半 */
    int c = max_cross(A, lo, mid, hi, &l3, &r3);   /* 合并: 跨中点 */
    if (a >= b && a >= c) { *bl = l1; *br = r1; return a; }
    if (b >= a && b >= c) { *bl = l2; *br = r2; return b; }
    *bl = l3; *br = r3; return c;
}

int main(void) {
    int n, A[1000];
    printf("输入元素个数 n (<= 1000): ");
    if (scanf("%d", &n) != 1 || n <= 0 || n > 1000) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个整数(可含负数): ", n);
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);
    int bl, br;
    int k = kadane(A, n, &bl, &br);
    printf("Kadane: 最大和 %d, 区间 [%d, %d]\n", k, bl, br);
    int dl, dr;
    int d = dc(A, 0, n, &dl, &dr);
    printf("分治:   最大和 %d, 区间 [%d, %d]\n", d, dl, dr);
    return 0;
}

#include <stdio.h>

/* Karatsuba 大整数乘法(64 位版): 拆成 16 位高低两半, 3 次递归乘法
 * 输入限制 a*b < 2^64; 中间积用 __int128 防溢出 */
typedef unsigned long long u64;
typedef unsigned __int128 u128;

u64 karatsuba(u64 x, u64 y) {
    if (x < 65536 && y < 65536) return x * y;   /* 递归基: 小数字直乘 */
    u64 x1 = x >> 16, x0 = x & 0xFFFF;          /* 分解: 高低两半 */
    u64 y1 = y >> 16, y0 = y & 0xFFFF;
    u64 z2 = karatsuba(x1, y1);                 /* 3 次递归乘法 */
    u64 z0 = karatsuba(x0, y0);
    u64 z1 = (u64)((u128)(x1 + x0) * (u128)(y1 + y0)) - z2 - z0;
    /* 合并: xy = z2*2^32 + z1*2^16 + z0 */
    return (u64)(((u128)z2 << 32) + ((u128)z1 << 16) + z0);
}

int main(void) {
    u64 a, b;
    printf("输入两个整数 a b (建议 <= 10^9, 保证 a*b < 2^64): ");
    if (scanf("%llu %llu", &a, &b) != 2) { printf("输入无效!\n"); return 1; }
    u64 p1 = a * b;                              /* 朴素乘法作对照 */
    u64 p2 = karatsuba(a, b);
    printf("朴素乘法结果: %llu\n", p1);
    printf("Karatsuba 结果: %llu\n", p2);
    printf("两者一致: %s\n", p1 == p2 ? "是" : "否");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

/* 平面最近点对: 分治。整数坐标, 全程用距离平方避免开方。
 * 条带内按 y 排序后, 每个点只需检查后面若干候选(抽屉原理保证至多 7 个)。
 * 注: 条带内用 qsort 每层排序, 演示版总 O(n log^2 n);
 * 按 y 预排序 + 归并保持可做到严格 O(n log n)。 */
typedef struct { long long x, y; } Pt;

long long dist2(Pt a, Pt b) {
    long long dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int cmp_x(const void *p, const void *q) {
    Pt *a = (Pt *)p, *b = (Pt *)q;
    if (a->x != b->x) return a->x > b->x ? 1 : -1;
    if (a->y != b->y) return a->y > b->y ? 1 : -1;
    return 0;
}

int cmp_y(const void *p, const void *q) {
    Pt *a = (Pt *)p, *b = (Pt *)q;
    if (a->y != b->y) return a->y > b->y ? 1 : -1;
    if (a->x != b->x) return a->x > b->x ? 1 : -1;
    return 0;
}

Pt P[5000], strip[5000];
long long best; Pt pa, pb;

void solve(int lo, int hi) {              /* 对按 x 排序的 P[lo..hi) 分治 */
    if (hi - lo <= 3) {                   /* 递归基: 小规模暴力 */
        for (int i = lo; i < hi; i++)
            for (int j = i + 1; j < hi; j++) {
                long long d = dist2(P[i], P[j]);
                if (d < best) { best = d; pa = P[i]; pb = P[j]; }
            }
        return;
    }
    int mid = (lo + hi) / 2;
    long long mid_x = P[mid].x;           /* 中线 */
    solve(lo, mid);                       /* 解决: 左半 */
    solve(mid, hi);                       /* 解决: 右半 */
    int k = 0;                            /* 合并: 收集条带内点 */
    for (int i = lo; i < hi; i++) {
        long long dx = P[i].x - mid_x;
        if (dx * dx < best) strip[k++] = P[i];
    }
    qsort(strip, k, sizeof(Pt), cmp_y);   /* 条带内按 y 排序 */
    for (int i = 0; i < k; i++)
        for (int j = i + 1; j < k; j++) {
            long long dy = strip[j].y - strip[i].y;
            if (dy * dy >= best) break;   /* y 差已超 best, 后面更远 */
            long long d = dist2(strip[i], strip[j]);
            if (d < best) { best = d; pa = strip[i]; pb = strip[j]; }
        }
}

int main(void) {
    int n;
    printf("输入点数 n (<= 5000): ");
    if (scanf("%d", &n) != 1 || n < 2 || n > 5000) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个点坐标 x y: ", n);
    for (int i = 0; i < n; i++) scanf("%lld %lld", &P[i].x, &P[i].y);
    qsort(P, n, sizeof(Pt), cmp_x);       /* 按 x 排序 */
    best = 1000000000000000000LL;         /* 初始化为无穷大 */
    solve(0, n);
    printf("最近距离平方: %lld\n", best);
    printf("最近距离: %.4f\n", sqrt((double)best));
    printf("最近点对: (%lld, %lld) 与 (%lld, %lld)\n", pa.x, pa.y, pb.x, pb.y);
    return 0;
}
